INSERT INTO cinematografia.continente (cod, nombre_es, nombre_en) VALUES ('EU', 'Europa', 'Europe');
INSERT INTO cinematografia.continente (cod, nombre_es, nombre_en) VALUES ('NA', 'América del Norte', 'North America');
INSERT INTO cinematografia.continente (cod, nombre_es, nombre_en) VALUES ('OC', 'Oceanía', 'Oceania');
INSERT INTO cinematografia.continente (cod, nombre_es, nombre_en) VALUES ('SA', 'América del Sur', 'South America');
INSERT INTO cinematografia.continente (cod, nombre_es, nombre_en) VALUES ('AN', 'Antártida', 'Antarctica');
INSERT INTO cinematografia.genero (cod, nombre, descripcion) VALUES ('AC', 'Acción', 'Películas cuyo argumento implica una interacción moral entre el «bien» y el «mal» llevada a su fin por la violencia o la fuerza física.');
INSERT INTO cinematografia.genero (cod, nombre, descripcion) VALUES ('AN', 'Animación', 'Películas compuestas por fotogramas dibujados a mano que, pasados rápidamente, producen ilusión de movimiento. También se incluyen en este género las películas creadas mediante animación por ordenador.');
INSERT INTO cinematografia.genero (cod, nombre, descripcion) VALUES ('AV', 'Aventuras', 'Películas que reflejan un mundo heroico de combates y a la acción, y en las que suele predominar la acción y valores caballerescos.');
INSERT INTO cinematografia.genero (cod, nombre, descripcion) VALUES ('BE', 'Bélica', 'Películas ambientadas en campos de batalla y posiciones que pertenecen a un tiempo de guerra.');
INSERT INTO cinematografia.genero (cod, nombre, descripcion) VALUES ('CF', 'Ciencia Ficción', 'Películas que se basan en un futuro cercano o muy lejano, donde se logra ver el avance de la tecnología y como ejecuta este en la historia.');
INSERT INTO cinematografia.genero (cod, nombre, descripcion) VALUES ('CO', 'Comedia', 'Películas realizadas con la intención de provocar humor, entretenimiento y/o risa en el espectador.');
INSERT INTO cinematografia.genero (cod, nombre, descripcion) VALUES ('DR', 'Drama', 'Películas que se centran principalmente en el desarrollo de un conflicto entre los protagonistas, o del protagonista con su entorno o consigo mismo.1​');
INSERT INTO cinematografia.genero (cod, nombre, descripcion) VALUES ('FA', 'Fantasía', 'Peliculas en las que la inexistencia de la tecnología nos da a entender que suceden en un tiempo pasado. La magia y animales mitológicos o sucesos sin una explicación lógica forman parte de este mundo. Son lo contrario al género de Ciencia Ficción.');
INSERT INTO cinematografia.genero (cod, nombre, descripcion) VALUES ('MD', 'Melodrama', 'Películas con una carga emocional o moral muy fuerte o emotiva, atendiendo al gusto de cada persona.');
INSERT INTO cinematografia.genero (cod, nombre, descripcion) VALUES ('MU', 'Musical', 'Películas que contienen interrupciones en su desarrollo, para dar un breve receso por medio de un fragmento musical cantado o acompañados de una coreografía.');
INSERT INTO cinematografia.genero (cod, nombre, descripcion) VALUES ('RO', 'Romance', 'Películas con un desarrollo romántico o amoroso entre dos personas.');
INSERT INTO cinematografia.genero (cod, nombre, descripcion) VALUES ('SU', 'Suspense', 'Películas realizadas con la intención de provocar tensión en el espectador. También suele utilizarse la palabra thriller para designar películas de este tipo, aunque hay sutiles diferencias.');
INSERT INTO cinematografia.genero (cod, nombre, descripcion) VALUES ('TR', 'Terror', 'Películas realizadas con la intención de provocar tensión, miedo y/o el sobresalto en la audiencia.');
INSERT INTO cinematografia.genero (cod, nombre, descripcion) VALUES ('WE', 'Wéstern', 'Género cinematográfico típico del cine estadounidense que se ambienta en el Viejo Oeste estadounidense. Las obras de este género son llamadas habitualmente ''películas del oeste'' o ''películas de vaqueros''');
